  <script>
    // === Menu ===
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    // === Theme ===
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || 'light';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      var icon = document.getElementById('themeIcon');
      var label = document.getElementById('themeLabel');
      if (icon) icon.textContent = t === 'dark' ? '🌙' : '☀️';
      if (label) label.textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    // === Scroll Reveal ===
    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });

    // === Number Counter ===
    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count);
        var prefix = el.dataset.prefix || '';
        var suffix = el.dataset.suffix || '';
        var start = performance.now();
        var duration = 1200;
        (function tick(now) {
          var p = Math.min((now - start) / duration, 1);
          var eased = 1 - Math.pow(1 - p, 3);
          var val = (target * eased);
          el.textContent = prefix + (target % 1 === 0 ? Math.round(val) : val.toFixed(1)) + suffix;
          if (p < 1) requestAnimationFrame(tick);
        })(start);
      });
    }
    var counterEl = document.querySelector('[data-count]');
    if (counterEl) {
      var cObs = new IntersectionObserver(function(entries) {
        entries.forEach(function(e) { if (e.isIntersecting) { animateCounters(); cObs.disconnect(); } });
      }, { threshold: 0.3 });
      cObs.observe(counterEl);
    }

    // === Download PNG ===
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2, filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); } });
        var a = document.createElement('a'); a.href = url;
        a.download = 'imf-weo-poster-2024-2026.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }

    // === Charts ===
    var chartsBuilt = false;

    function getChartColors() {
      var s = getComputedStyle(document.documentElement);
      return {
        text: s.getPropertyValue('--text').trim(),
        textSecondary: s.getPropertyValue('--text-secondary').trim(),
        border: s.getPropertyValue('--border').trim(),
        accent: s.getPropertyValue('--accent').trim(),
        warning: s.getPropertyValue('--warning').trim() || '#E8912D',
        positive: s.getPropertyValue('--positive').trim(),
        negative: s.getPropertyValue('--negative').trim(),
      };
    }

    function resetCanvas(id) {
      var old = document.getElementById(id);
      if (!old) return null;
      var parent = old.parentNode;
      var canvas = document.createElement('canvas');
      canvas.id = id;
      canvas.setAttribute('role', 'img');
      canvas.setAttribute('aria-label', old.getAttribute('aria-label') || 'Chart');
      parent.replaceChild(canvas, old);
      return canvas;
    }

    function buildCharts() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }

      var colors = getChartColors();
      var isDark = document.documentElement.classList.contains('theme-dark');
      var gridColor = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,40,68,0.08)';
      var textColor = colors.textSecondary;

      // === Growth Chart ===
      if (window.growthChartInst) { try { window.growthChartInst.destroy(); } catch(e) {} }
      var gc = resetCanvas('growthChart');
      if (gc) {
        gc.setAttribute('aria-label', 'Line chart showing global growth projections across 8 WEO editions from 2024 to 2026');
        var labels = ['Jul 2024', 'Oct 2024', 'Jan 2025', 'Apr 2025', 'Jul 2025', 'Oct 2025', 'Jan 2026', 'Apr 2026'];
        var currentYear = [3.2, 3.2, null, null, null, null, null, null];
        var nextYear = [3.3, 3.3, 3.3, null, 3.0, null, 3.3, null];
        var yearAfter = [null, null, 3.3, null, 3.1, null, 3.2, null];

        window.growthChartInst = new Chart(gc, {
          type: 'line',
          data: {
            labels: labels,
            datasets: [
              {
                label: 'Current-Year Forecast',
                data: currentYear,
                borderColor: '#2563eb',
                backgroundColor: 'rgba(37,99,235,0.08)',
                borderWidth: 3,
                pointRadius: 6,
                pointBackgroundColor: '#2563eb',
                pointBorderColor: isDark ? '#141414' : '#fff',
                pointBorderWidth: 2,
                pointHoverRadius: 8,
                tension: 0.2,
                spanGaps: false
              },
              {
                label: 'Next-Year Forecast',
                data: nextYear,
                borderColor: '#4A90D9',
                backgroundColor: 'rgba(74,144,217,0.08)',
                borderWidth: 3,
                pointRadius: 6,
                pointBackgroundColor: '#4A90D9',
                pointBorderColor: isDark ? '#141414' : '#fff',
                pointBorderWidth: 2,
                pointHoverRadius: 8,
                tension: 0.2,
                spanGaps: false
              },
              {
                label: 'Year-After Forecast',
                data: yearAfter,
                borderColor: '#7AB8E0',
                backgroundColor: 'rgba(122,184,224,0.08)',
                borderWidth: 3,
                pointRadius: 6,
                pointBackgroundColor: '#7AB8E0',
                pointBorderColor: isDark ? '#141414' : '#fff',
                pointBorderWidth: 2,
                pointHoverRadius: 8,
                tension: 0.2,
                spanGaps: false
              },
              {
                label: 'Pre-Pandemic Average (3.8%)',
                data: [3.8, 3.8, 3.8, 3.8, 3.8, 3.8, 3.8, 3.8],
                borderColor: 'rgba(232,145,45,0.7)',
                borderWidth: 2,
                borderDash: [10, 6],
                pointRadius: 0,
                pointHoverRadius: 0,
                fill: false,
                tension: 0
              },
              {
                label: '3.0–3.3% Band (Upper)',
                data: [3.3, 3.3, 3.3, 3.3, 3.3, 3.3, 3.3, 3.3],
                borderColor: 'transparent',
                backgroundColor: isDark ? 'rgba(74,144,217,0.12)' : 'rgba(37,99,235,0.08)',
                fill: '+1',
                pointRadius: 0,
                pointHoverRadius: 0,
                tension: 0
              },
              {
                label: '3.0–3.3% Band (Lower)',
                data: [3.0, 3.0, 3.0, 3.0, 3.0, 3.0, 3.0, 3.0],
                borderColor: 'transparent',
                backgroundColor: 'transparent',
                fill: false,
                pointRadius: 0,
                pointHoverRadius: 0,
                tension: 0
              }
            ]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            layout: { padding: { top: 20, right: 30, bottom: 10, left: 20 } },
            interaction: { mode: 'index', intersect: false },
            plugins: {
              tooltip: {
                enabled: true,
                mode: 'index',
                intersect: false,
                padding: 14,
                cornerRadius: 8,
                titleFont: { size: 15, family: 'Inter' },
                bodyFont: { size: 14, family: 'Inter' },
                filter: function(item) { return item.datasetIndex < 4; },
                callbacks: {
                  label: function(ctx) {
                    if (ctx.raw === null) return ctx.dataset.label + ': No point estimate';
                    return ctx.dataset.label + ': ' + ctx.raw.toFixed(1) + '%';
                  }
                }
              },
              legend: { display: false },
              annotation: {}
            },
            scales: {
              x: {
                ticks: {
                  color: textColor,
                  font: { size: 15, family: 'Inter', weight: '500' },
                  maxRotation: 0
                },
                grid: { color: gridColor, lineWidth: 1 }
              },
              y: {
                min: 2.5,
                max: 4.2,
                ticks: {
                  color: textColor,
                  font: { size: 14, family: 'Inter' },
                  callback: function(v) { return v.toFixed(1) + '%'; },
                  stepSize: 0.2
                },
                grid: { color: gridColor, lineWidth: 1 }
              }
            }
          }
        });
      }

      // === Inflation Chart ===
      if (window.inflationChartInst) { try { window.inflationChartInst.destroy(); } catch(e) {} }
      var ic = resetCanvas('inflationChart');
      if (ic) {
        ic.setAttribute('aria-label', 'Grouped bar chart comparing global headline inflation versus US inflation from 2024 to 2026');
        window.inflationChartInst = new Chart(ic, {
          type: 'bar',
          data: {
            labels: ['2024', '2025 (proj)', '2026 (proj)'],
            datasets: [
              {
                label: 'Global Headline Inflation',
                data: [5.8, 4.3, 3.5],
                backgroundColor: isDark ? 'rgba(74,144,217,0.7)' : 'rgba(37,99,235,0.75)',
                borderRadius: 4,
                barPercentage: 0.7,
                categoryPercentage: 0.65
              },
              {
                label: 'US Inflation',
                data: [4.1, 3.5, 3.0],
                backgroundColor: isDark ? 'rgba(232,145,45,0.7)' : 'rgba(194,113,10,0.75)',
                borderRadius: 4,
                barPercentage: 0.7,
                categoryPercentage: 0.65
              },
              {
                label: '2% Target',
                data: [2.0, 2.0, 2.0],
                type: 'line',
                borderColor: isDark ? 'rgba(239,68,68,0.6)' : 'rgba(220,38,38,0.5)',
                borderWidth: 2,
                borderDash: [8, 5],
                pointRadius: 0,
                pointHoverRadius: 0,
                fill: false,
                tension: 0
              }
            ]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            layout: { padding: { top: 10, right: 20, bottom: 0, left: 10 } },
            plugins: {
              tooltip: {
                enabled: true,
                padding: 12,
                cornerRadius: 8,
                titleFont: { size: 14, family: 'Inter' },
                bodyFont: { size: 13, family: 'Inter' },
                callbacks: {
                  label: function(ctx) { return ctx.dataset.label + ': ' + ctx.raw.toFixed(1) + '%'; }
                }
              },
              legend: {
                display: true,
                position: 'top',
