642	    function animateCounters() {
643	      document.querySelectorAll('[data-count]').forEach(function(el) {
644	        if (el.dataset.counted) return;
645	        el.dataset.counted = '1';
646	        var target = parseFloat(el.dataset.count);
647	        var prefix = el.dataset.prefix || '';
648	        var suffix = el.dataset.suffix || '';
649	        var start = performance.now();
650	        var duration = 1200;
651	        (function tick(now) {
652	          var p = Math.min((now - start) / duration, 1);
653	          var eased = 1 - Math.pow(1 - p, 3);
654	          var val = (target * eased);
655	          el.textContent = prefix + (target % 1 === 0 ? Math.round(val) : val.toFixed(1)) + suffix;
656	          if (p < 1) requestAnimationFrame(tick);
657	        })(start);
658	      });
659	    }
