661	    if (counterEl) {
662	      var cObs = new IntersectionObserver(function(entries) {
663	        entries.forEach(function(e) { if (e.isIntersecting) { animateCounters(); cObs.disconnect(); } });
664	      }, { threshold: 0.3 });
665	      cObs.observe(counterEl);
666	    }
