[metadata] {"type": "text", "file": {"filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>\n<html lang=\"en\" class=\"theme-light\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Global Economy in the Shadow of War – IMF WEO Trends 2024-2026</title>\n  <link href=\"/app/libs/fonts/inter.css\" rel=\"stylesheet\">\n  <script src=\"/app/libs/chart.js\"></script>\n  <script>Chart.defaults.animation = false;</script>\n  <script src=\"/app/libs/html-to-image.js\"></script>\n  <style>\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n    :root { interpolate-size: allow-keywords; }\n\n    html.theme-dark {\n      --bg: #0A0A0A; --surface: #141414; --surface-hover: #1C1C1C;\n      --border: rgba(255,255,255,0.08);\n      --text: #EDEDED; --text-secondary: #999;\n      --accent: #4A90D9; --accent-secondary: #6BB3E0;\n      --positive: #10b981; --negative: #f43f5e; --warning: #E8912D;\n      --imf-blue: #002244; --imf-blue-mid: #003366; --imf-blue-light: #1a4a72;\n      --amber: #E8912D; --amber-light: rgba(232,145,45,0.15);\n      --chart-bg: #0f1a2e;\n    }\n    html.theme-light {\n      --bg: #FAFAF9; --surface: #FFFFFF; --surface-hover: #F5F5F4;\n      --border: rgba(0,40,68,0.08);\n      --text: #0f172a; --text-secondary: #4a6280;\n      --accent: #002244; --accent-secondary: #003d7a;\n      --positive: #059669; --negative: #e11d48; --warning: #D97706;\n      --imf-blue: #002244; --imf-blue-mid: #003366; --imf-blue-light: #e8eef5;\n      --amber: #C2710A; --amber-light: rgba(194,113,10,0.1);\n      --chart-bg: #f0f4f8;\n    }\n\n    body {\n      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;\n      background: var(--bg); color: var(--text);\n      width: 3179px; height: 4494px;\n      overflow: hidden;\n      -webkit-font-smoothing: antialiased;\n      letter-spacing: -0.01em;\n      font-feature-settings: 'cv11', 'ss01';\n      display: flex; flex-direction: column;\n    }\n    h1,h2,h3,h4 { color: var(--text); letter-spacing: -0.03em; line-height: 1.1; text-wrap: balance; }\n    h1 { font-weight: 800; }\n    h2 { font-weight: 700; }\n    h3 { font-weight: 600; }\n\n    @keyframes fadeInUp { from { opacity:0; transform:translateY(24px); } to { opacity:1; transform:translateY(0); } }\n    @keyframes fadeIn { from { opacity:0; } to { opacity:1; } }\n    .animate { animation: fadeInUp 0.6s ease-out both; }\n    .animate.delay-1 { animation-delay: 0.1s; }\n    .animate.delay-2 { animation-delay: 0.2s; }\n    .animate.delay-3 { animation-delay: 0.3s; }\n    .animate.delay-4 { animation-delay: 0.4s; }\n    .animate.delay-5 { animation-delay: 0.5s; }\n    .animate.delay-6 { animation-delay: 0.6s; }\n\n    .reveal { opacity:0; transform:translateY(24px); transition: opacity 0.6s ease, transform 0.6s ease; }\n    .reveal.visible { opacity:1; transform:translateY(0); }\n\n    @media (prefers-reduced-motion: reduce) {\n      *, *::before, *::after { animation: none !important; transition: none !important; }\n      .reveal { opacity:1; transform:none; }\n    }\n    @media print {\n      body { background: white !important; color: black !important; }\n      .viz-menu { display: none !important; }\n      .card { break-inside: avoid; border: 1px solid #ddd; box-shadow: none; }\n      * { print-color-adjust: exact; -webkit-print-color-adjust: exact; }\n    }\n    @page { margin: 0.5in; }\n\n    .viz-menu { position: fixed; top: 16px; right: 16px; z-index: 9999; }\n    .viz-menu-toggle {\n      width: 44px; height: 44px; border-radius: 12px;\n      background: var(--surface); border: 1px solid var(--border);\n      color: var(--text); cursor: pointer; display: flex;\n      align-items: center; justify-content: center;\n      backdrop-filter: blur(12px); transition: all 0.2s;\n    }\n    .viz-menu-toggle:hover { background: var(--surface-hover); }\n    .viz-menu-dropdown {\n      position: absolute; top: 52px; right: 0; min-width: 200px;\n      background: var(--surface); border: 1px solid var(--border);\n      border-radius: 12px; padding: 8px;\n      opacity: 0; visibility: hidden; transform: translateY(-8px);\n      transition: all 0.2s; backdrop-filter: blur(16px);\n    }\n    .viz-menu-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }\n    .viz-menu-dropdown button {\n      width: 100%; padding: 10px 14px; border: none; border-radius: 8px;\n      background: transparent; color: var(--text); font-size: 14px;\n      font-family: inherit; cursor: pointer; text-align: left;\n      display: flex; align-items: center; gap: 10px; transition: background 0.15s;\n    }\n    .viz-menu-dropdown button:hover { background: var(--surface-hover); }\n\n    .skip-to-content {\n      position: absolute; top: -40px; left: 6px; background: var(--accent);\n      color: white; padding: 8px 12px; text-decoration: none;\n      border-radius: 4px; opacity: 0; pointer-events: none; z-index: 10000;\n    }\n    .skip-to-content:focus { top: 6px; opacity: 1; pointer-events: auto; }\n\n    /* ===== POSTER LAYOUT ===== */\n    .poster-header {\n      background: var(--imf-blue);\n      color: #fff;\n      padding: 72px 96px 56px;\n      position: relative;\n      overflow: hidden;\n    }\n    .poster-header::after {\n      content: '';\n      position: absolute; top: 0; right: 0; bottom: 0; width: 40%;\n      background: radial-gradient(ellipse at 80% 50%, rgba(74,144,217,0.15) 0%, transparent 70%);\n    }\n    .poster-header h1 {\n      font-size: 84px; font-weight: 800; color: #fff;\n      line-height: 1.05; margin-bottom: 20px;\n      max-width: 2400px; letter-spacing: -0.04em;\n    }\n    .poster-subtitle {\n      font-size: 34px; color: rgba(255,255,255,0.75);\n      font-weight: 400; max-width: 2200px; line-height: 1.4;\n    }\n    .poster-venue {\n      margin-top: 24px; font-size: 22px; color: rgba(255,255,255,0.5);\n      text-transform: uppercase; letter-spacing: 0.12em; font-weight: 600;\n    }\n\n    .poster-body {\n      flex: 1;\n      padding: 56px 96px 40px;\n      display: flex; flex-direction: column;\n      gap: 48px;\n    }\n\n    /* KPI strip */\n    .kpi-strip {\n      display: grid;\n      grid-template-columns: repeat(5, 1fr);\n      gap: 24px;\n    }\n    .kpi-card {\n      background: var(--surface); border: 1px solid var(--border);\n      border-radius: 12px; padding: 32px 28px; text-align: center;\n      transition: box-shadow 0.2s;\n    }\n    .kpi-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,0.06); }\n    .kpi-card.accent-kpi { border-left: 4px solid var(--accent); }\n    .kpi-card.warning-kpi { border-left: 4px solid var(--amber); }\n    .kpi-value {\n      font-size: 56px; font-weight: 800; color: var(--accent);\n      letter-spacing: -0.04em; line-height: 1;\n    }\n    .kpi-card.warning-kpi .kpi-value { color: var(--amber); }\n    .kpi-label {\n      font-size: 18px; color: var(--text-secondary);\n      margin-top: 8px; font-weight: 500; line-height: 1.3;\n    }\n    .kpi-source {\n      font-size: 14px; color: var(--text-secondary); opacity: 0.6;\n      margin-top: 4px;\n    }\n\n    /* Main content grid */\n    .content-grid {\n      flex: 1;\n      display: grid;\n      grid-template-columns: 1.6fr 1fr;\n      grid-template-rows: auto auto;\n      gap: 40px;\n    }\n\n    .section-card {\n      background: var(--surface); border: 1px solid var(--border);\n      border-radius: 12px; padding: 40px;\n      transition: box-shadow 0.2s;\n    }\n    .section-card:hover { box-shadow: 0 4px 20px rgba(0,0,0,0.06); }\n    .section-title {\n      font-size: 32px; font-weight: 700; color: var(--text);\n      margin-bottom: 20px; letter-spacing: -0.03em;\n      display: flex; align-items: center; gap: 14px;\n    }\n    .section-title .icon-badge {\n      width: 44px; height: 44px; border-radius: 10px;\n      display: flex; align-items: center; justify-content: center;\n      flex-shrink: 0;\n    }\n    .icon-badge.blue { background: rgba(0,34,68,0.1); color: var(--imf-blue); }\n    .icon-badge.amber { background: var(--amber-light); color: var(--amber); }\n\n    .theme-light .icon-badge.blue { background: rgba(0,34,68,0.08); }\n    .theme-dark .icon-badge.blue { background: rgba(74,144,217,0.15); }\n    .theme-dark .icon-badge.amber { background: rgba(232,145,45,0.15); }\n\n    /* Growth chart area */\n    .growth-section {\n      grid-column: 1 / -1;\n    }\n    .chart-container {\n      height: 600px; padding: 24px; border-radius: 12px;\n      background: var(--chart-bg); position: relative;\n    }\n    .chart-legend-custom {\n      display: flex; gap: 32px; margin-top: 16px; flex-wrap: wrap;\n    }\n    .legend-item {\n      display: flex; align-items: center; gap: 8px;\n      font-size: 17px; color: var(--text-secondary);\n    }\n    .legend-swatch {\n      width: 28px; height: 4px; border-radius: 2px;\n    }\n    .legend-swatch.band { height: 14px; opacity: 0.3; border-radius: 3px; }\n\n    /* Risk callout */\n    .risk-callout {\n      border-left: 5px solid var(--amber);\n      background: var(--amber-light);\n      border-radius: 0 12px 12px 0;\n      padding: 36px 40px;\n    }\n    .risk-callout .callout-label {\n      font-size: 15px; text-transform: uppercase; letter-spacing: 0.1em;\n      color: var(--amber); font-weight: 700; margin-bottom: 8px;\n    }\n    .risk-callout .callout-value {\n      font-size: 40px; font-weight: 800; color: var(--amber);\n      letter-spacing: -0.03em; line-height: 1.1; margin-bottom: 12px;\n    }\n    .risk-callout .callout-desc {\n      font-size: 19px; color: var(--text-secondary); line-height: 1.5;\n    }\n\n    /* Risk pillars */\n    .risk-pillars {\n      display: grid; grid-template-columns: 1fr 1fr;\n      gap: 16px; margin-top: 24px;\n    }\n    .risk-pillar {\n      background: var(--surface); border: 1px solid var(--border);\n      border-radius: 10px; padding: 20px 22px;\n      display: flex; align-items: flex-start; gap: 14px;\n    }\n    .risk-pillar:hover { background: var(--surface-hover); }\n    .pillar-icon {\n      width: 36px; height: 36px; border-radius: 8px;\n      background: var(--amber-light);\n      display: flex; align-items: center; justify-content: center;\n      flex-shrink: 0;\n    }\n    .pillar-name {\n      font-size: 18px; font-weight: 600; color: var(--text);\n      margin-bottom: 4px;\n    }\n    .pillar-desc {\n      font-size: 15px; color: var(--text-secondary); line-height: 1.4;\n    }\n\n    /* Inflation section */\n    .inflation-chart-container {\n      height: 400px; padding: 24px; border-radius: 12px;\n      background: var(--chart-bg);\n    }\n\n    /* Policy timeline */\n    .policy-timeline {\n      position: relative; padding-left: 28px;\n    }\n    .policy-timeline::before {\n      content: ''; position: absolute; left: 8px; top: 8px; bottom: 8px;\n      width: 3px; background: var(--border); border-radius: 2px;\n    }\n    .timeline-item {\n      position: relative; padding: 0 0 28px 28px;\n    }\n    .timeline-item:last-child { padding-bottom: 0; }\n    .timeline-item::before {\n      content: ''; position: absolute; left: -24px; top: 6px;\n      width: 13px; height: 13px; border-radius: 50%;\n      background: var(--accent); border: 3px solid var(--bg);\n    }\n    .timeline-item:last-child::before { background: var(--amber); }\n    .timeline-period {\n      font-size: 14px; text-transform: uppercase; letter-spacing: 0.08em;\n      color: var(--accent); font-weight: 700; margin-bottom: 4px;\n    }\n    .timeline-item:last-child .timeline-period { color: var(--amber); }\n    .timeline-focus {\n      font-size: 19px; font-weight: 600; color: var(--text); line-height: 1.3;\n    }\n\n    /* Themes grid */\n    .themes-grid {\n      display: grid; grid-template-columns: 1fr 1fr;\n      gap: 14px;\n    }\n    .theme-pill {\n      background: var(--surface); border: 1px solid var(--border);\n      border-radius: 10px; padding: 18px 20px;\n      display: flex; align-items: center; gap: 12px;\n      font-size: 17px; font-weight: 500; color: var(--text);\n    }\n    .theme-pill:hover { background: var(--surface-hover); }\n    .theme-pill .pill-dot {\n      width: 10px; height: 10px; border-radius: 50%;\n      background: var(--accent); flex-shrink: 0;\n    }\n\n    /* Bottom row */\n    .bottom-row {\n      display: grid;\n      grid-template-columns: 1fr 1fr 1fr;\n      gap: 40px;\n    }\n\n    /* Footer */\n    .poster-footer {\n      background: var(--imf-blue);\n      color: rgba(255,255,255,0.6);\n      padding: 28px 96px;\n      display: flex; justify-content: space-between; align-items: center;\n      font-size: 18px;\n    }\n    .poster-footer strong { color: rgba(255,255,255,0.85); font-weight: 600; }\n\n    /* Central message banner */\n    .central-message {\n      background: var(--imf-blue);\n      color: #fff;\n      padding: 36px 60px;\n      border-radius: 12px;\n      text-align: center;\n      grid-column: 1 / -1;\n    }\n    .central-message .msg-label {\n      font-size: 15px; text-transform: uppercase; letter-spacing: 0.12em;\n      color: rgba(255,255,255,0.55); font-weight: 600; margin-bottom: 8px;\n    }\n    .central-message .msg-text {\n      font-size: 36px; font-weight: 700; letter-spacing: -0.02em;\n      line-height: 1.3; color: #fff;\n    }\n    .central-message .msg-sub {\n      font-size: 20px; color: rgba(255,255,255,0.65);\n      margin-top: 10px; max-width: 2200px; margin-left: auto; margin-right: auto;\n      line-height: 1.5;\n    }\n\n    @media (max-width: 375px) {\n      body { overflow-x: hidden; }\n    }\n  </style>\n</head>\n<body>\n  <a href=\"#main-content\" class=\"skip-to-content\">Skip to content</a>\n\n  <div class=\"viz-menu\">\n    <button class=\"viz-menu-toggle\" onclick=\"toggleMenu()\" aria-label=\"Menu\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\">\n        <line x1=\"3\" y1=\"5\" x2=\"17\" y2=\"5\"/><line x1=\"3\" y1=\"10\" x2=\"17\" y2=\"10\"/><line x1=\"3\" y1=\"15\" x2=\"17\" y2=\"15\"/>\n      </svg>\n    </button>\n    <div class=\"viz-menu-dropdown\" id=\"vizMenuDropdown\">\n      <button onclick=\"cycleTheme()\"><span id=\"themeIcon\">☀️</span><span id=\"themeLabel\">Light</span></button>\n      <button onclick=\"downloadImage()\"><span>📥</span><span>Download PNG</span></button>\n      <button onclick=\"window.print()\"><span>🖨️</span><span>Print / PDF</span></button>\n    </div>\n  </div>\n\n  <main id=\"main-content\" role=\"main\">\n\n    <!-- HEADER -->\n    <section class=\"poster-header animate\">\n      <div class=\"poster-venue\">IMF-World Bank Annual Meetings Research Symposium</div>\n      <h1>Global Economy in the Shadow of War</h1>\n      <div class=\"poster-subtitle\">IMF World Economic Outlook Trends 2024–2026: A Synthesis of Eight Editions Tracking Growth, Risk, and Evolving Policy Priorities</div>\n    </section>\n\n    <div class=\"poster-body\">\n\n      <!-- KPI STRIP -->\n      <section class=\"kpi-strip animate delay-1\" aria-label=\"Key metrics\">\n        <div class=\"kpi-card accent-kpi\">\n          <div class=\"kpi-value\" data-count=\"3.0\" data-suffix=\"%\">3.0%</div>\n          <div class=\"kpi-label\">Global Growth 2025</div>\n          <div class=\"kpi-source\">WEO Jul 2025</div>\n        </div>\n        <div class=\"kpi-card accent-kpi\">\n          <div class=\"kpi-value\">3.3%</div>\n          <div class=\"kpi-label\">Global Growth 2026</div>\n          <div class=\"kpi-source\">WEO Jan 2026</div>\n        </div>\n        <div class=\"kpi-card accent-kpi\">\n          <div class=\"kpi-value\">3.2%</div>\n          <div class=\"kpi-label\">Global Growth 2027</div>\n          <div class=\"kpi-source\">WEO Jan 2026</div>\n        </div>\n        <div class=\"kpi-card accent-kpi\">\n          <div class=\"kpi-value\">8</div>\n          <div class=\"kpi-label\">WEO Editions Reviewed</div>\n          <div class=\"kpi-source\">Jul 2024 – Apr 2026</div>\n        </div>\n        <div class=\"kpi-card warning-kpi\">\n          <div class=\"kpi-value\" style=\"font-size:36px; line-height:1.2;\">Downside</div>\n          <div class=\"kpi-label\">Risk Balance — All Editions</div>\n          <div class=\"kpi-source\">Consistent finding</div>\n        </div>\n      </section>\n\n      <!-- CENTRAL MESSAGE -->\n      <section class=\"central-message animate delay-2\">\n        <div class=\"msg-label\">Central Finding</div>\n        <div class=\"msg-text\">Persistent Mediocrity with Growing Fragility</div>\n        <div class=\"msg-sub\">Global growth isn't collapsing, but it's not recovering either — hovering in a narrow 3.0–3.3% band, well below the pre-pandemic 3.8% average, while the balance of risks remains consistently tilted to the downside.</div>\n      </section>\n\n      <!-- GROWTH CHART — VISUAL CENTERPIECE -->\n      <section class=\"section-card growth-section animate delay-3\">\n        <h2 class=\"section-title\">\n          <span class=\"icon-badge blue\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 17l6-6 4 4 8-8\"/><path d=\"M17 7h4v4\"/></svg>\n          </span>\n          Global Growth Projections: A Narrow Band of Mediocrity\n        </h2>\n        <div role=\"img\" aria-label=\"Line chart showing IMF global growth projections from July 2024 to April 2026, ranging between 3.0% and 3.3%, with a pre-pandemic average reference line at 3.8%\">\n          <div class=\"chart-container\">\n            <canvas id=\"growthChart\"></canvas>\n          </div>\n        </div>\n        <div class=\"chart-legend-custom\">\n          <div class=\"legend-item\"><div class=\"legend-swatch\" style=\"background:#4A90D9;\"></div> Current-Year Forecast</div>\n          <div class=\"legend-item\"><div class=\"legend-swatch\" style=\"background:#7AB8E0;\"></div> Next-Year Forecast</div>\n          <div class=\"legend-item\"><div class=\"legend-swatch\" style=\"background:#E8912D; opacity:0.7;\"></div> Pre-Pandemic Avg (3.8%)</div>\n          <div class=\"legend-item\"><div class=\"legend-swatch band\" style=\"background:#4A90D9;\"></div> 3.0–3.3% Band</div>\n        </div>\n      </section>\n\n      <!-- BOTTOM THREE-COLUMN AREA -->\n      <div class=\"bottom-row\">\n\n        <!-- RISKS -->\n        <section class=\"section-card animate delay-4\">\n          <h2 class=\"section-title\">\n            <span class=\"icon-badge amber\">\n              <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><circle cx=\"12\" cy=\"17\" r=\"0.5\"/></svg>\n            </span>\n            Dominant Downside Risks\n          </h2>\n\n          <div class=\"risk-callout\">\n            <div class=\"callout-label\">Persistent Finding Across All 8 Editions</div>\n            <div class=\"callout-value\">\"Tilted to the Downside\"</div>\n            <div class=\"callout-desc\">The IMF has consistently assessed the balance of risks as skewed negative throughout every WEO edition from July 2024 to April 2026.</div>\n          </div>\n\n          <div class=\"risk-pillars\">\n            <div class=\"risk-pillar\">\n              <div class=\"pillar-icon\">\n                <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"2\" y=\"7\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M16 7V5a4 4 0 00-8 0v2\"/></svg>\n              </div>\n              <div>\n                <div class=\"pillar-name\">Trade Policy Escalation</div>\n                <div class=\"pillar-desc\">Tariffs and retaliatory measures, with front-loading masking damage</div>\n              </div>\n            </div>\n            <div class=\"risk-pillar\">\n              <div class=\"pillar-icon\">\n                <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"/><path d=\"M12 2a15.3 15.3 0 014 10 15.3 15.3 0 01-4 10 15.3 15.3 0 01-4-10 15.3 15.3 0 014-10z\"/></svg>\n              </div>\n              <div>\n                <div class=\"pillar-name\">Geopolitical Tensions</div>\n                <div class=\"pillar-desc\">Middle East conflicts, broader security concerns, and war</div>\n              </div>\n            </div>\n            <div class=\"risk-pillar\">\n              <div class=\"pillar-icon\">\n                <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2\"/><rect x=\"9\" y=\"9\" width=\"6\" height=\"6\"/><path d=\"M15 2v2\"/><path d=\"M15 20v2\"/><path d=\"M2 15h2\"/><path d=\"M20 15h2\"/><path d=\"M9 2v2\"/><path d=\"M9 20v2\"/><path d=\"M2 9h2\"/><path d=\"M20 9h2\"/></svg>\n              </div>\n              <div>\n                <div class=\"pillar-name\">Technology Re-evaluation</div>\n                <div class=\"pillar-desc\">AI and tech investment expectations may face correction</div>\n              </div>\n            </div>\n            <div class=\"risk-pillar\">\n              <div class=\"pillar-icon\">\n                <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 2v20M17 5H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6\"/></svg>\n              </div>\n              <div>\n                <div class=\"pillar-name\">Persistent Services Inflation</div>\n                <div class=\"pillar-desc\">US inflation to return to target more gradually than peers</div>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <!-- INFLATION -->\n        <section class=\"section-card animate delay-5\">\n          <h2 class=\"section-title\">\n            <span class=\"icon-badge blue\">\n              <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 2v20M17 5H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6\"/></svg>\n            </span>\n            Inflation & Monetary Policy\n          </h2>\n          <div role=\"img\" aria-label=\"Bar chart showing global inflation declining but US inflation persisting above target, with renewed pressures emerging in 2026\">\n            <div class=\"inflation-chart-container\">\n              <canvas id=\"inflationChart\"></canvas>\n            </div>\n          </div>\n          <div style=\"margin-top:20px;\">\n            <div style=\"display:flex; gap:12px; flex-wrap:wrap;\">\n              <div style=\"flex:1; min-width:200px; padding:16px 18px; background:var(--surface-hover); border-radius:8px; border-left:3px solid var(--positive);\">\n                <div style=\"font-size:15px; font-weight:600; color:var(--positive);\">Global Disinflation</div>\n                <div style=\"font-size:14px; color:var(--text-secondary); margin-top:4px;\">Headline inflation on a declining trajectory through 2026</div>\n              </div>\n              <div style=\"flex:1; min-width:200px; padding:16px 18px; background:var(--surface-hover); border-radius:8px; border-left:3px solid var(--warning);\">\n                <div style=\"font-size:15px; font-weight:600; color:var(--warning);\">US Exception</div>\n                <div style=\"font-size:14px; color:var(--text-secondary); margin-top:4px;\">Above target longer; services inflation sticky</div>\n              </div>\n              <div style=\"flex:1; min-width:200px; padding:16px 18px; background:var(--surface-hover); border-radius:8px; border-left:3px solid var(--negative);\">\n                <div style=\"font-size:15px; font-weight:600; color:var(--negative);\">Renewed Pressure</div>\n                <div style=\"font-size:14px; color:var(--text-secondary); margin-top:4px;\">Defense spending and supply disruptions by Apr 2026</div>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <!-- POLICY EVOLUTION + THEMES -->\n        <section class=\"section-card animate delay-6\" style=\"display:flex; flex-direction:column; gap:32px;\">\n          <div>\n            <h2 class=\"section-title\">\n              <span class=\"icon-badge blue\">\n                <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\n              </span>\n              Evolving Policy Priorities\n            </h2>\n            <div class=\"policy-timeline\">\n              <div class=\"timeline-item\">\n                <div class=\"timeline-period\">Mid-2024</div>\n                <div class=\"timeline-focus\">Manage disinflation; begin monetary easing carefully</div>\n              </div>\n              <div class=\"timeline-item\">\n                <div class=\"timeline-period\">Late 2024</div>\n                <div class=\"timeline-focus\">Policy pivot; ensure fiscal sustainability</div>\n              </div>\n              <div class=\"timeline-item\">\n                <div class=\"timeline-period\">Early 2025</div>\n                <div class=\"timeline-focus\">Rebuild fiscal buffers; address demographic and gender gaps</div>\n              </div>\n              <div class=\"timeline-item\">\n                <div class=\"timeline-period\">Mid-2025</div>\n                <div class=\"timeline-focus\">Restore confidence and predictability amid tariff uncertainty</div>\n              </div>\n              <div class=\"timeline-item\">\n                <div class=\"timeline-period\">Late 2025</