      position: absolute; top: -50%; right: -10%; width: 60%; height: 200%;
      background: radial-gradient(ellipse, rgba(74,144,217,0.12) 0%, transparent 60%);
      pointer-events: none;
    }
    .poster-header h1 {
      font-size: 96px; font-weight: 800; color: #fff;
      line-height: 1.02; margin-bottom: 24px;
      max-width: 2600px; letter-spacing: -0.04em;
      position: relative; z-index: 1;
    }
    .poster-subtitle {
      font-size: 36px; color: rgba(255,255,255,0.72);
      font-weight: 400; max-width: 2400px; line-height: 1.45;
      position: relative; z-index: 1;
    }
    .poster-venue {
      margin-bottom: 28px; font-size: 22px; color: rgba(255,255,255,0.45);
      text-transform: uppercase; letter-spacing: 0.14em; font-weight: 600;
      position: relative; z-index: 1;
    }

    .poster-body {
      flex: 1;
      padding: 48px 100px;
      display: flex; flex-direction: column;
      gap: 44px;
    }

    /* KPI strip */
    .kpi-strip {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 28px;
    }
    .kpi-card {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 14px; padding: 36px 32px; text-align: center;
      transition: box-shadow 0.2s;
    }
    .kpi-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,0.06); }
    .kpi-card.accent-kpi { border-top: 4px solid var(--accent); }
    .kpi-card.warning-kpi { border-top: 4px solid var(--amber); }
    .kpi-value {
      font-size: 64px; font-weight: 800; color: var(--accent);
      letter-spacing: -0.04em; line-height: 1;
    }
    .kpi-card.warning-kpi .kpi-value { color: var(--amber); }
    .kpi-label {
      font-size: 20px; color: var(--text-secondary);
      margin-top: 12px; font-weight: 500; line-height: 1.3;
    }
    .kpi-source {
      font-size: 16px; color: var(--text-secondary); opacity: 0.55;
      margin-top: 6px;
    }

    .section-card {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 14px; padding: 48px;
      transition: box-shadow 0.2s;
    }
    .section-card:hover { box-shadow: 0 4px 20px rgba(0,0,0,0.06); }
    .section-title {
      font-size: 36px; font-weight: 700; color: var(--text);
      margin-bottom: 24px; letter-spacing: -0.03em;
      display: flex; align-items: center; gap: 16px;
    }
    .section-title .icon-badge {
      width: 48px; height: 48px; border-radius: 12px;
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
    }
    .icon-badge.blue { background: rgba(0,34,68,0.08); color: var(--imf-blue); }
    .icon-badge.amber { background: var(--amber-light); color: var(--amber); }
    .theme-dark .icon-badge.blue { background: rgba(74,144,217,0.15); }
    .theme-dark .icon-badge.amber { background: rgba(232,145,45,0.15); }

    /* Central message */
    .central-message {
      background: linear-gradient(135deg, #001a36 0%, #002244 50%, #003366 100%);
      color: #fff;
      padding: 44px 72px;
      border-radius: 14px;
      text-align: center;
      position: relative; overflow: hidden;
    }
    .central-message::before {
      content: '';
      position: absolute; inset: 0;
      background: radial-gradient(ellipse at 50% 50%, rgba(74,144,217,0.08) 0%, transparent 70%);
    }
    .central-message .msg-label {
      font-size: 16px; text-transform: uppercase; letter-spacing: 0.14em;
      color: rgba(255,255,255,0.5); font-weight: 600; margin-bottom: 10px;
      position: relative;
    }
    .central-message .msg-text {
      font-size: 44px; font-weight: 800; letter-spacing: -0.03em;
      line-height: 1.2; color: #fff; position: relative;
    }
    .central-message .msg-sub {
      font-size: 22px; color: rgba(255,255,255,0.6);
      margin-top: 14px; max-width: 2400px; margin-left: auto; margin-right: auto;
      line-height: 1.5; position: relative;
    }

    /* Growth chart */
    .chart-container {
      height: 720px; padding: 32px; border-radius: 12px;
      background: var(--chart-bg); position: relative;
    }
    .chart-legend-custom {
      display: flex; gap: 40px; margin-top: 20px; flex-wrap: wrap;
    }
    .legend-item {
      display: flex; align-items: center; gap: 10px;
      font-size: 19px; color: var(--text-secondary); font-weight: 500;
    }
    .legend-swatch { width: 32px; height: 5px; border-radius: 3px; }
    .legend-swatch.band { height: 16px; opacity: 0.3; border-radius: 4px; }
    .legend-swatch.dashed {
      background: repeating-linear-gradient(90deg, #E8912D 0, #E8912D 8px, transparent 8px, transparent 14px);
      opacity: 0.7;
    }

    /* Bottom two-row structure */
    .bottom-area {
      flex: 1;
      display: grid;
      grid-template-columns: 1.1fr 1fr 1fr;
      gap: 36px;
    }

    /* Risk callout */
    .risk-callout {
      border-left: 5px solid var(--amber);
      background: var(--amber-light);
      border-radius: 0 12px 12px 0;
      padding: 40px 44px;
      margin-bottom: 28px;
    }
    .risk-callout .callout-label {
      font-size: 16px; text-transform: uppercase; letter-spacing: 0.1em;
      color: var(--amber); font-weight: 700; margin-bottom: 10px;
    }
    .risk-callout .callout-value {
      font-size: 44px; font-weight: 800; color: var(--amber);
      letter-spacing: -0.03em; line-height: 1.1; margin-bottom: 14px;
    }
    .risk-callout .callout-desc {
      font-size: 20px; color: var(--text-secondary); line-height: 1.5;
    }
    .risk-pillars {
      display: grid; grid-template-columns: 1fr;
      gap: 16px;
    }
    .risk-pillar {
      background: var(--surface-hover); border: 1px solid var(--border);
      border-radius: 12px; padding: 24px 26px;
      display: flex; align-items: flex-start; gap: 16px;
    }
    .risk-pillar:hover { box-shadow: 0 2px 8px rgba(0,0,0,0.04); }
    .pillar-icon {
      width: 40px; height: 40px; border-radius: 10px;
      background: var(--amber-light);
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
    }
    .pillar-name { font-size: 20px; font-weight: 600; color: var(--text); margin-bottom: 4px; }
    .pillar-desc { font-size: 17px; color: var(--text-secondary); line-height: 1.4; }

    /* Inflation */
    .inflation-chart-container {
      height: 460px; padding: 28px; border-radius: 12px;
      background: var(--chart-bg);
    }
    .insight-cards {
      display: flex; flex-direction: column; gap: 14px; margin-top: 24px;
    }
    .insight-card {
      padding: 20px 22px; background: var(--surface-hover);
      border-radius: 10px; border-left: 4px solid var(--positive);
    }
    .insight-card.warn { border-left-color: var(--warning); }
    .insight-card.neg { border-left-color: var(--negative); }
    .insight-title { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
    .insight-title.green { color: var(--positive); }
    .insight-title.amber { color: var(--warning); }
    .insight-title.red { color: var(--negative); }
    .insight-desc { font-size: 16px; color: var(--text-secondary); line-height: 1.4; }

    /* Policy timeline */
    .policy-timeline { position: relative; padding-left: 32px; }
    .policy-timeline::before {
      content: ''; position: absolute; left: 10px; top: 10px; bottom: 10px;
      width: 3px; background: linear-gradient(180deg, var(--accent) 0%, var(--amber) 100%);
      border-radius: 2px; opacity: 0.3;
    }
    .timeline-item { position: relative; padding: 0 0 32px 32px; }
    .timeline-item:last-child { padding-bottom: 0; }
    .timeline-item::before {
      content: ''; position: absolute; left: -26px; top: 7px;
      width: 15px; height: 15px; border-radius: 50%;
      background: var(--accent); border: 3px solid var(--surface);
      box-shadow: 0 0 0 2px var(--accent);
    }
    .timeline-item:last-child::before {
      background: var(--amber);
      box-shadow: 0 0 0 2px var(--amber);
    }
    .timeline-period {
      font-size: 15px; text-transform: uppercase; letter-spacing: 0.09em;
      color: var(--accent); font-weight: 700; margin-bottom: 5px;
    }
    .timeline-item:last-child .timeline-period { color: var(--amber); }
    .timeline-focus { font-size: 20px; font-weight: 500; color: var(--text); line-height: 1.35; }

    /* Themes */
    .themes-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
    .theme-pill {
      background: var(--surface-hover); border: 1px solid var(--border);
      border-radius: 10px; padding: 20px 22px;
      display: flex; align-items: center; gap: 14px;
      font-size: 18px; font-weight: 500; color: var(--text);
    }
    .theme-pill:hover { box-shadow: 0 2px 8px rgba(0,0,0,0.04); }
    .pill-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--accent); flex-shrink: 0; }

    /* Footer */
    .poster-footer {
      background: linear-gradient(135deg, #001a36 0%, #002244 100%);
      color: rgba(255,255,255,0.55);
      padding: 32px 100px;
      display: flex; justify-content: space-between; align-items: center;
      font-size: 19px;
    }
    .poster-footer strong { color: rgba(255,255,255,0.82); font-weight: 600; }

    @media (max-width: 375px) { body { overflow-x: hidden; } }
  </style>
</head>
<body>
  <a href="#main-content" class="skip-to-content">Skip to content</a>

  <div class="viz-menu">
